#include "Types.r"						/* For ICON resource */#include "InstallerTypes.r"/*	AppleShare Apple II Setup installer script.		This installer script tells Installer 3.0.1 how to install the files:		Apple //e Boot Blocks		ProDOS16 Boot Blocks		ProDOS16 Image		P8		BASIC.System	These files are used to allow Apple IIe and IIGS computers to start up	over the network from a file server.  These files get installed in the	server's Server Folder (which is the blessed folder on the disk).		15-Feb-91	MSD		Written from scratch to work with the new Installer						script format for 3.0.1.*//*				  AppleShare				Apple II Setup	This is an installer script for Installer version 3.0 (specifically, the	one that ships on the Mac System 6.0.7 System Tools disk).  It installs the	boot block files, P8, and BASIC.System on an AppleShare file server so that	Apple IIe's and IIGS's can boot from it.		16-Jun-91	MSD		Changed the Splash Screen PICT.  It now uses Garamond						and the wording was changed slightly so that it is						correct for AppleShare File Server 2.0 and 3.0.	28-Oct-91	MSD		Fixed to work with Installer 3.2 (which ships with						AppleShare 3.0 and System 7.0).  Removed the default						map ('indm' resource) and replaced it with 'infr' and						'inrl' resources.  Changed release date for 'icmt' to						use shell variable "todayhex".							11-May-92	MSD		Removed the Customize screen since it provides the same						functionality as the Easy Install screen.  Removed the						'icmt' and ICON resources since they are only used for						custom installs.*//*======================================================================================================================================	Now begins the actual resource declarations for the	Apple II Setup Disk.	======================================================================================================================================*/#define IIeBlocks	101#define	IIGSBlocks	102#define	IIGSImage	103#define	ProDOS8		104#define	BASIC		105#define	TargIIe		201#define	TargIIGS	202#define	TargImg		203#define	TargP8		204#define	TargBASIC	205#define TheRules	301			/* List of rules */#define EasyRule	302			/* Rule list for Easy Install */#define A2Setup		1000#define	SetupDisk	"Apple II Setup:"/*	The package that installs all the Apple II booting files.*/resource 'inpk' (A2Setup,"Apple II Script") {	format0 {		doesntShowOnCustom,								/* Not visible in the Custom Install */		removable,										/* Can be removed */		dontForceRestart,								/* no need to force a restart/reboot */		0,												/* ICMT resource ID */		0,												/* Package size, to be filled in by ScriptCheck */		"AppleShare Apple II Setup (v" $$Shell("thisvers") ")",		/* Package name */		{												/* the parts */			'infa', IIeBlocks;							/* File: Apple //e Boot Blocks */			'infa', IIGSBlocks;							/* File: ProDOS16 Boot Blocks */			'infa', IIGSImage;							/* File: ProDOS16 Image */			'infa', ProDOS8;							/* File: P8 */			'infa', BASIC;								/* File: BASIC.System */		}	}};/*	Installer rule framework.  This specifies which rules Installer should pick based	on what is available in the machine and on disk.*/resource 'infr' (TheRules) {	format0 {{		pickFirst,				/* Choose the first rule that matches */		{			EasyRule			/* Prefer the Easy Install rule */		}	}}};/*	Installer rules.  This is how the installer decides whether to install on the current	machine, system software, etc.*/resource 'inrl' (EasyRule, "Easy Install") {	format0 {{		addPackages {{			A2Setup				/* Just the Apple II Setup package (everything) */		}},		addUserDescription {			"Click Install to place version " $$Shell("thisvers") " of\n"			"¥ Apple II Network Startup"		}	}}};/*	Now come all of the file specifications.*/resource 'infs' (IIeBlocks, "source IIe Blocks") {	'ZSYS',												/* Type */	'MACS',												/* Creator */	0,													/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	SetupDisk"System Folder:Apple //e Boot Blocks"		/* path name */};resource 'infs' (IIGSBlocks, "source IIGS Blocks") {	'ZSYS',												/* Type */	'MACS',												/* Creator */	0,													/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	SetupDisk"System Folder:ProDOS16 Boot Blocks"		/* path name */};resource 'infs' (IIGSImage, "source IIGS Image") {	'ZSYS',												/* Type */	'MACS',												/* Creator */	0,													/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	SetupDisk"System Folder:ProDOS16 Image"				/* path name */};resource 'infs' (ProDOS8, "source P8") {	'PSYS',												/* Type */	'pdos',												/* Creator */	0,													/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	SetupDisk"System Folder:P8"							/* path name */};resource 'infs' (BASIC, "source BASIC") {	'PSYS',												/* Type */	'pdos',												/* Creator */	0,													/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	SetupDisk"System Folder:BASIC.System"				/* path name */};resource 'infs' (TargIIe, "target IIe Blocks") {	'ZSYS',								/* Type */	'MACS',								/* Creator */	0,									/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	"Blessed:Apple //e Boot Blocks"		/* path name */};resource 'infs' (TargIIGS, "target IIGS Blocks") {	'ZSYS',								/* Type */	'MACS',								/* Creator */	0,									/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	"Blessed:ProDOS16 Boot Blocks"		/* path name */};resource 'infs' (TargImg, "target IIGS Image") {	'ZSYS',								/* Type */	'MACS',								/* Creator */	0,									/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	"Blessed:ProDOS16 Image"			/* path name */};resource 'infs' (TargP8, "target P8") {	'PSYS',								/* Type */	'pdos',								/* Creator */	0,									/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	"Blessed:P8"						/* path name */};resource 'infs' (TargBASIC, "target BASIC") {	'PSYS',								/* Type */	'pdos',								/* Creator */	0,									/* Creation date, filled in by ScriptCheck */	noSearchForFile,	TypeCrMustMatch,	"Blessed:BASIC.System"				/* path name */};/*	File Atoms*/resource 'infa' (IIeBlocks, "IIe Blocks") {	format0 {		delRemove,			/* Delete file to remove */		noDelInstall,		/* Don't delete file before install (may be newer version) */		copy,				/* Copy file to install */		leaveAloneIfNewer,	/* Do allow newer versions of this file */		noKeepExisting,		/* Don't keep existing target file (unless it is newer) */		noUpdateOnly,		/* Copy it even if it doesn't exist on target disk */		rsrcFork,			/* Copy the resource fork */		dataFork,			/* Copy the data fork */				TargIIe,			/* target filespec */		IIeBlocks,			/* source filespec */		0,					/* atom size, filled in by ScriptCheck */		"Apple //e Boot Blocks"	};};resource 'infa' (IIGSBlocks, "IIGS Blocks") {	format0 {		delRemove,			/* Delete file to remove */		noDelInstall,		/* Don't delete file before install (may be newer version) */		copy,				/* Copy file to install */		leaveAloneIfNewer,	/* Do allow newer versions of this file */		noKeepExisting,		/* Don't keep existing target file (unless it is newer) */		noUpdateOnly,		/* Copy it even if it doesn't exist on target disk */		rsrcFork,			/* Copy the resource fork */		dataFork,			/* Copy the data fork */				TargIIGS,			/* target filespec */		IIGSBlocks,			/* source filespec */		0,					/* atom size, filled in by ScriptCheck */		"ProDOS16 Boot Blocks"	};};resource 'infa' (IIGSImage, "IIGS Image") {	format0 {		delRemove,			/* Delete file to remove */		noDelInstall,		/* Don't delete file before install (may be newer version) */		copy,				/* Copy file to install */		leaveAloneIfNewer,	/* Do allow newer versions of this file */		noKeepExisting,		/* Don't keep existing target file (unless it is newer) */		noUpdateOnly,		/* Copy it even if it doesn't exist on target disk */		rsrcFork,			/* Copy the resource fork */		dataFork,			/* Copy the data fork */				TargImg,			/* target filespec */		IIGSImage,			/* source filespec */		0,					/* atom size, filled in by ScriptCheck */		"ProDOS16 Image"	};};resource 'infa' (ProDOS8, "P8") {	format0 {		delRemove,			/* Delete file to remove */		noDelInstall,		/* Don't delete file before install (may be newer version) */		copy,				/* Copy file to install */		leaveAloneIfNewer,	/* Do allow newer versions of this file */		noKeepExisting,		/* Don't keep existing target file (unless it is newer) */		noUpdateOnly,		/* Copy it even if it doesn't exist on target disk */		rsrcFork,			/* Copy the resource fork */		dataFork,			/* Copy the data fork */				TargP8,			/* target filespec */		ProDOS8,			/* source filespec */		0,					/* atom size, filled in by ScriptCheck */		"P8"	};};resource 'infa' (BASIC, "BASIC") {	format0 {		delRemove,			/* Delete file to remove */		noDelInstall,		/* Don't delete file before install (may be newer version) */		copy,				/* Copy file to install */		leaveAloneIfNewer,	/* Do allow newer versions of this file */		noKeepExisting,		/* Don't keep existing target file (unless it is newer) */		noUpdateOnly,		/* Copy it even if it doesn't exist on target disk */		rsrcFork,			/* Copy the resource fork */		dataFork,			/* Copy the data fork */				TargBASIC,			/* target filespec */		BASIC,				/* source filespec */		0,					/* atom size, filled in by ScriptCheck */		"BASIC.System"	};};/*	The PICT displayed as a splash screen.		You can use the following command to DeRez the resource:		derez -m 80 -only PICT "Apple II Setup:Apple II Script" Types.r*/resource 'PIC